import { createContext, useEffect, useState } from 'react'
import PropTypes from 'prop-types'

const ThemeContext = createContext()

const ThemeProvider = ({ children }) => {
  // default to dark if there's no saved preference
  const [themeName, setThemeName] = useState(() => {
    try {
      return localStorage.getItem('themeName') || 'dark'
    } catch (e) {
      return 'dark'
    }
  })

  useEffect(() => {
    // If the user already has a saved preference, keep it. Otherwise use system preference.
    let saved
    try {
      saved = localStorage.getItem('themeName')
    } catch (e) {
      saved = null
    }

    const darkMediaQuery = window.matchMedia('(prefers-color-scheme: dark)')

    if (!saved) {
      setThemeName(darkMediaQuery.matches ? 'dark' : 'light')
    }

    const handler = (e) => {
      setThemeName(e.matches ? 'dark' : 'light')
    }

    darkMediaQuery.addEventListener('change', handler)
    return () => darkMediaQuery.removeEventListener('change', handler)
  }, [])

  const toggleTheme = () => {
    const name = themeName === 'dark' ? 'light' : 'dark'
    localStorage.setItem('themeName', name)
    setThemeName(name)
  }

  return (
    <ThemeContext.Provider value={[{ themeName, toggleTheme }]}>
      {children}
    </ThemeContext.Provider>
  )
}

ThemeProvider.propTypes = {
  children: PropTypes.node.isRequired,
}

export { ThemeProvider, ThemeContext }
