import uniqid from 'uniqid'
import GitHubIcon from '@material-ui/icons/GitHub'
import LaunchIcon from '@material-ui/icons/Launch'
import './ProjectContainer.css'

const ProjectContainer = ({ project }) => {
  const openReport = async () => {
    if (!project.report) return
    const url = project.report.startsWith('http')
      ? project.report
      : `${process.env.PUBLIC_URL}/${project.report}`

    try {
      // try a lightweight HEAD request to ensure file exists
      const res = await fetch(url, { method: 'HEAD' })
      if (res.ok) {
        window.open(url, '_blank', 'noopener,noreferrer')
        return
      }
      // if HEAD failed (not ok), still attempt to open the URL so deployment can be checked
      window.open(url, '_blank', 'noopener,noreferrer')
      // optionally notify user that file may be missing
      // eslint-disable-next-line no-alert
      alert(`Report may not be available at ${url}. If you just added it, try reloading the page.`)
    } catch (err) {
      // network error - still attempt to open
      window.open(url, '_blank', 'noopener,noreferrer')
    }
  }

  return (
    <div className='project'>
      <div className='project__inner'>
      {project.image && (
        <div className='project__image'>
          <img
            src={
              project.image.startsWith('http')
                ? project.image
                : `${process.env.PUBLIC_URL}/images/${project.image}`
            }
            alt={`${project.name} screenshot`}
            className='project__img'
          />
        </div>
      )}

      <div className='project__content'>
        <h3>{project.name}</h3>

        {/* Support either a string paragraph or an array of bullet points for description */}
        {Array.isArray(project.description) ? (
          <ul className='project__description-list'>
            {project.description.map((item) => (
              <li key={uniqid()} className='project__description-item'>
                {item}
              </li>
            ))}
          </ul>
        ) : (
          <p className='project__description'>{project.description}</p>
        )}

        {project.stack && (
          <ul className='project__stack'>
            {project.stack.map((item) => (
              <li key={uniqid()} className='project__stack-item'>
                {item}
              </li>
            ))}
          </ul>
        )}

        <div className='project__links'>
          {project.report && (
            <button type='button' onClick={openReport} className='btn btn--outline'>
              Report
            </button>
          )}

          {project.sourceCode && (
            <a
              href={project.sourceCode}
              aria-label='source code'
              className='link link--icon'
            >
              <GitHubIcon />
            </a>
          )}

          {project.livePreview && (
            <a
              href={project.livePreview}
              aria-label='live preview'
              className='link link--icon'
            >
              <LaunchIcon />
            </a>
          )}

          
        </div>
      </div>
    </div>
  </div>
  )
}

export default ProjectContainer
